#!/usr/bin/env python3
"""Structural checks for Incident Commons v0.1 reports.

This validates format, not truth, legal reportability, severity, or completeness
of an investigation. Unknown values are permitted where the schema permits them.
"""

import argparse
import json
import re
import sys
from datetime import datetime
from pathlib import Path

SCHEMA_VERSION = "0.1"
EVIDENCE = {"observed", "reported_by_third_party", "inferred", "unknown"}
CONFIDENCE = {"low", "medium", "high", "unknown"}
SEVERITY = {"critical", "high", "medium", "low", "unknown"}
EVENT_STATUS = {"ongoing", "contained", "resolved", "unknown"}
HANDLING = {"restricted", "regulator_confidential", "public"}
EMAIL = re.compile(r"^[^\s@]+@[^\s@]+\.[^\s@]+$")


def _is_string(value):
    return isinstance(value, str) and bool(value.strip())


def _string(data, key, path, errors, allow_unknown=False):
    value = data.get(key)
    if allow_unknown and value is None:
        return
    if not _is_string(value):
        errors.append(f"{path}.{key} must be a non-empty string" + (" or null" if allow_unknown else ""))


def _mapping(value, path, errors):
    if not isinstance(value, dict):
        errors.append(f"{path} must be an object")
        return False
    return True


def _list(value, path, errors, nonempty=False):
    if not isinstance(value, list):
        errors.append(f"{path} must be an array")
        return False
    if nonempty and not value:
        errors.append(f"{path} must not be empty")
    return True


def _timestamp(value, path, errors, nullable=False):
    if nullable and value is None:
        return
    if not _is_string(value):
        errors.append(f"{path} must be an RFC 3339 timestamp" + (" or null" if nullable else ""))
        return
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        errors.append(f"{path} is not a valid ISO/RFC 3339 timestamp: {value!r}")
        return
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        errors.append(f"{path} must include an explicit timezone offset")


def _choice(data, key, allowed, path, errors):
    value = data.get(key)
    if value not in allowed:
        errors.append(f"{path}.{key} must be one of {sorted(allowed)}")


def _harms(items, path, errors):
    if not _list(items, path, errors):
        return
    for index, item in enumerate(items):
        item_path = f"{path}[{index}]"
        if not _mapping(item, item_path, errors):
            continue
        for key in ("category", "description", "scale"):
            _string(item, key, item_path, errors)
        _choice(item, "evidence_status", EVIDENCE, item_path, errors)


def validate_report(report):
    """Return a list of human-readable validation errors; an empty list passes."""
    errors = []
    if not _mapping(report, "report", errors):
        return errors

    if report.get("schema_version") != SCHEMA_VERSION:
        errors.append(f"schema_version must be {SCHEMA_VERSION!r}")
    for key in ("report_id", "submitted_at", "evidence_status"):
        if key not in report:
            errors.append(f"missing required field: {key}")
    _string(report, "report_id", "report", errors)
    _timestamp(report.get("submitted_at"), "submitted_at", errors)
    _choice(report, "report_type", {"initial", "investigation"}, "report", errors)
    _choice(report, "evidence_status", EVIDENCE, "report", errors)

    entity = report.get("reporting_entity")
    if _mapping(entity, "reporting_entity", errors):
        for key in ("name", "role", "jurisdiction"):
            _string(entity, key, "reporting_entity", errors)

    contact = report.get("contact")
    if _mapping(contact, "contact", errors):
        for key in ("role", "secure_channel"):
            _string(contact, key, "contact", errors)
        email = contact.get("email")
        if not _is_string(email) or not EMAIL.match(email):
            errors.append("contact.email must be a non-empty email-shaped string")

    model = report.get("model")
    if _mapping(model, "model", errors):
        for key in ("stable_id", "version", "developer", "deployment_id", "deployment_context"):
            _string(model, key, "model", errors)

    event = report.get("event")
    if _mapping(event, "event", errors):
        for key in ("summary", "detection_source", "affected_scale"):
            _string(event, key, "event", errors)
        _timestamp(event.get("first_observed_at"), "event.first_observed_at", errors, nullable=True)
        _timestamp(event.get("occurrence_start_at"), "event.occurrence_start_at", errors, nullable=True)
        _timestamp(event.get("occurrence_end_at"), "event.occurrence_end_at", errors, nullable=True)
        _timestamp(event.get("detected_at"), "event.detected_at", errors)
        _choice(event, "status", EVENT_STATUS, "event", errors)
        _choice(event, "severity", SEVERITY, "event", errors)
        _choice(event, "confidence", CONFIDENCE, "event", errors)
        _harms(event.get("actual_harms"), "event.actual_harms", errors)
        _harms(event.get("potential_harms"), "event.potential_harms", errors)

    timeline = report.get("timeline")
    if _list(timeline, "timeline", errors, nonempty=True):
        previous = None
        for index, entry in enumerate(timeline):
            path = f"timeline[{index}]"
            if not _mapping(entry, path, errors):
                continue
            _string(entry, "description", path, errors)
            _choice(entry, "evidence_status", EVIDENCE, path, errors)
            at = entry.get("at")
            _timestamp(at, f"{path}.at", errors)
            try:
                current = datetime.fromisoformat(at.replace("Z", "+00:00")) if _is_string(at) else None
            except ValueError:
                current = None
            if current is not None and previous is not None and current < previous:
                errors.append(f"{path}.at is earlier than the preceding timeline entry")
            if current is not None:
                previous = current

    response = report.get("response")
    if _mapping(response, "response", errors):
        for key in ("current_operational_status", "support_or_remedy"):
            _string(response, key, "response", errors)
        _timestamp(response.get("next_update_at"), "response.next_update_at", errors)
        actions = response.get("containment_actions")
        if _list(actions, "response.containment_actions", errors):
            for index, action in enumerate(actions):
                path = f"response.containment_actions[{index}]"
                if not _mapping(action, path, errors):
                    continue
                _string(action, "action", path, errors)
                _string(action, "observed_effect", path, errors)
                _timestamp(action.get("at"), f"{path}.at", errors)

    uncertainties = report.get("uncertainties")
    if _list(uncertainties, "uncertainties", errors):
        for index, value in enumerate(uncertainties):
            if not _is_string(value):
                errors.append(f"uncertainties[{index}] must be a non-empty string")

    distribution = report.get("distribution")
    if _mapping(distribution, "distribution", errors):
        _choice(distribution, "handling", HANDLING, "distribution", errors)
        _string(distribution, "public_summary", "distribution", errors)
        if not isinstance(distribution.get("confidential_annex"), bool):
            errors.append("distribution.confidential_annex must be true or false")
        reasons = distribution.get("redaction_reasons")
        if _list(reasons, "distribution.redaction_reasons", errors):
            for index, value in enumerate(reasons):
                if not _is_string(value):
                    errors.append(f"distribution.redaction_reasons[{index}] must be a non-empty string")

    related = report.get("related_reports", [])
    if _list(related, "related_reports", errors):
        for index, relation in enumerate(related):
            path = f"related_reports[{index}]"
            if not _mapping(relation, path, errors):
                continue
            for key in ("relationship", "report_id"):
                _string(relation, key, path, errors)

    if report.get("report_type") == "investigation":
        has_initial_link = isinstance(related, list) and any(
            isinstance(item, dict) and item.get("relationship") == "initial_report"
            and _is_string(item.get("report_id"))
            for item in related
        )
        if not has_initial_link:
            errors.append("investigation must link to its initial report with relationship='initial_report'")
        analysis = report.get("analysis")
        if _mapping(analysis, "analysis", errors):
            _string(analysis, "methods", "analysis", errors)
            _string(analysis, "changes_from_initial", "analysis", errors)
            factors = analysis.get("contributing_factors")
            if _list(factors, "analysis.contributing_factors", errors, nonempty=True):
                for index, factor in enumerate(factors):
                    if not _is_string(factor):
                        errors.append(f"analysis.contributing_factors[{index}] must be a non-empty string")
        actions = report.get("corrective_actions")
        if _list(actions, "corrective_actions", errors, nonempty=True):
            for index, action in enumerate(actions):
                path = f"corrective_actions[{index}]"
                if not _mapping(action, path, errors):
                    continue
                for key in ("action", "owner_role", "due_at", "verification_method"):
                    _string(action, key, path, errors)
                _timestamp(action.get("due_at"), f"{path}.due_at", errors)

    return errors


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reports", nargs="+", type=Path)
    args = parser.parse_args(argv)
    failed = False
    for path in args.reports:
        try:
            with path.open(encoding="utf-8") as handle:
                report = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            print(f"FAIL {path}: {exc}")
            failed = True
            continue
        errors = validate_report(report)
        if errors:
            failed = True
            print(f"FAIL {path}")
            for error in errors:
                print(f"  - {error}")
        else:
            print(f"PASS {path} (structural checks only)")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

